import React, { useEffect, useState } from "react"
import { AppointmentRequest, ApprovePayload } from "../../../hooks/useAppointmentRequests"

interface Props {
  request: AppointmentRequest
  adminEmail: string
  onConfirm: (id: string, payload: ApprovePayload) => Promise<void>
  onClose: () => void
}

const TIME_SLOTS: string[] = []
for (let h = 7; h <= 18; h++) {
  TIME_SLOTS.push(`${String(h).padStart(2, "0")}:00`)
  if (h < 18) TIME_SLOTS.push(`${String(h).padStart(2, "0")}:30`)
}

const SERVICE_DURATIONS: Record<string, number> = {
  "tire-change": 90,
  "oil-change": 30,
  "general-inspection": 60,
  "brake-change": 120,
  custom: 60,
}

function defaultDuration(serviceType: string): number {
  return SERVICE_DURATIONS[serviceType] ?? 60
}

export default function ApproveRequestModal({ request, adminEmail, onConfirm, onClose }: Props) {
  const [date, setDate] = useState(request.preferredDates[0] ?? "")
  const [timeSlot, setTimeSlot] = useState("09:00")
  const [serviceType, setServiceType] = useState(request.serviceType)
  const [duration, setDuration] = useState(defaultDuration(request.serviceType))
  const [notes, setNotes] = useState(request.notes)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState("")

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onClose()
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [onClose])

  async function handleConfirm() {
    if (!date) { setError("Date is required"); return }
    if (!timeSlot) { setError("Time slot is required"); return }
    setError("")
    setSaving(true)
    try {
      const [y, m, d] = date.split("-").map(Number)
      const [hh, mm] = timeSlot.split(":").map(Number)
      const apptDate = new Date(y, m - 1, d, hh, mm, 0, 0)
      await onConfirm(request.id, {
        date: apptDate,
        timeSlot,
        serviceType,
        estimatedDuration: duration,
        notes,
        adminEmail,
      })
    } catch {
      setError("Failed to create appointment. Please try again.")
    } finally {
      setSaving(false)
    }
  }

  const serviceLabel =
    request.serviceType === "custom"
      ? request.customDescription || "Custom"
      : request.serviceType.replace(/-/g, " ").replace(/\b\w/g, c => c.toUpperCase())

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} />
      <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-md max-h-[90vh] flex flex-col">

        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100 flex-shrink-0">
          <div>
            <h2 className="font-semibold text-gray-800">Approve Request</h2>
            <p className="text-xs text-gray-400 mt-0.5">{request.clientName}</p>
          </div>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-700 text-xl leading-none">✕</button>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto px-6 py-5 space-y-4">

          {/* Client summary */}
          <div className="bg-gray-50 rounded-lg p-3 text-sm space-y-0.5">
            <p className="font-medium text-gray-800">{request.clientName}</p>
            <p className="text-gray-500">{request.phone}{request.email ? ` · ${request.email}` : ""}</p>
            <p className="text-gray-600 mt-1">
              <span className="font-medium">Service:</span> {serviceLabel}
            </p>
            {request.preferredDates.length > 0 && (
              <p className="text-gray-500 text-xs mt-1">
                Preferred dates: {request.preferredDates.join(", ")}
                {request.preferredTimeOfDay !== "any" && ` · ${request.preferredTimeOfDay}`}
              </p>
            )}
            {request.notes && (
              <p className="text-gray-500 text-xs mt-1 italic">"{request.notes}"</p>
            )}
          </div>

          {/* Appointment fields */}
          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">
              Date <span className="text-red-500">*</span>
            </label>
            <input
              type="date"
              value={date}
              onChange={e => setDate(e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">
              Time <span className="text-red-500">*</span>
            </label>
            <select
              value={timeSlot}
              onChange={e => setTimeSlot(e.target.value)}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
            >
              {TIME_SLOTS.map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">Estimated duration (min)</label>
            <input
              type="number"
              value={duration}
              min={15}
              step={15}
              onChange={e => setDuration(parseInt(e.target.value, 10) || 60)}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">Notes</label>
            <textarea
              value={notes}
              onChange={e => setNotes(e.target.value)}
              rows={2}
              className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
            />
          </div>

          {error && <p className="text-xs text-red-500">{error}</p>}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-100 flex gap-3 justify-end flex-shrink-0">
          <button
            onClick={onClose}
            className="px-4 py-2 border border-gray-200 text-gray-700 text-sm rounded-lg hover:bg-gray-50 transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={handleConfirm}
            disabled={saving}
            className="px-4 py-2 bg-green-600 hover:bg-green-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50"
          >
            {saving ? "Creating…" : "Confirm & Create Appointment"}
          </button>
        </div>
      </div>
    </div>
  )
}
