import React, { useState, ReactNode } from "react"
import { Link, navigate } from "gatsby"
import { useAuth } from "../../context/AuthContext"
import { useAppointmentRequests } from "../../hooks/useAppointmentRequests"

interface NavItem {
  label: string
  icon: string
  to: string
}

const NAV_ITEMS: NavItem[] = [
  { label: "Calendar", icon: "📅", to: "/admin/dashboard" },
  { label: "Clients", icon: "👥", to: "/admin/clients" },
  { label: "Service Reports", icon: "📋", to: "/admin/reports/services" },
  { label: "Financial Reports", icon: "💰", to: "/admin/reports/financial" },
  { label: "Settings", icon: "⚙️", to: "/admin/settings" },
  { label: "Requests", icon: "🔔", to: "/admin/requests" },
]

interface AdminLayoutProps {
  children: ReactNode
  currentPath: string
}

export default function AdminLayout({ children, currentPath }: AdminLayoutProps) {
  const { currentUser, logout } = useAuth()
  const { pendingCount } = useAppointmentRequests()
  const [collapsed, setCollapsed] = useState(false)
  const [drawerOpen, setDrawerOpen] = useState(false)

  async function handleLogout() {
    await logout()
    navigate("/admin/login")
  }

  const sidebarContent = (mobile = false) => (
    <nav className="flex-1 px-2 space-y-1 mt-4">
      {NAV_ITEMS.map(item => {
        const isActive = currentPath === item.to
        const base =
          "flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-colors w-full text-left"
        const isRequests = item.to === "/admin/requests"

        return (
          <Link
            key={item.label}
            to={item.to}
            onClick={() => mobile && setDrawerOpen(false)}
            className={`${base} ${
              collapsed && !mobile ? "justify-center" : ""
            } ${
              isActive
                ? "bg-blue-600 text-white"
                : "text-gray-300 hover:bg-gray-800 hover:text-white"
            }`}
          >
            {/* Icon + badge wrapper */}
            <span className="relative flex-shrink-0">
              <span className="text-lg leading-none">{item.icon}</span>
              {isRequests && pendingCount > 0 && (
                <span className="absolute -top-1.5 -right-1.5 bg-red-500 text-white text-[10px] font-bold rounded-full min-w-[16px] h-4 flex items-center justify-center px-1 leading-none">
                  {pendingCount > 9 ? "9+" : pendingCount}
                </span>
              )}
            </span>
            {(!collapsed || mobile) && <span>{item.label}</span>}
            {/* Badge also in label area when expanded */}
            {(!collapsed || mobile) && isRequests && pendingCount > 0 && (
              <span className="ml-auto bg-red-500 text-white text-[10px] font-bold rounded-full min-w-[18px] h-4 flex items-center justify-center px-1">
                {pendingCount > 9 ? "9+" : pendingCount}
              </span>
            )}
          </Link>
        )
      })}
    </nav>
  )

  return (
    <div className="flex min-h-screen bg-gray-100">
      {/* Desktop sidebar */}
      <aside
        className={`hidden md:flex flex-col bg-gray-900 text-gray-200 transition-all duration-200 relative flex-shrink-0 ${
          collapsed ? "w-16" : "w-60"
        }`}
      >
        <div className={`px-4 pt-6 pb-2 flex items-center ${collapsed ? "justify-center" : "justify-between"}`}>
          {!collapsed && (
            <div>
              <span className="text-white font-bold text-base">GarageCarlos</span>
              <span className="block text-xs text-gray-400">Admin Panel</span>
            </div>
          )}
          <button
            onClick={() => setCollapsed(c => !c)}
            className="text-gray-400 hover:text-white p-1 rounded transition-colors flex-shrink-0"
            aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            {collapsed ? "›" : "‹"}
          </button>
        </div>
        {sidebarContent()}
      </aside>

      {/* Mobile drawer overlay */}
      {drawerOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 md:hidden"
          onClick={() => setDrawerOpen(false)}
        />
      )}

      {/* Mobile drawer */}
      <aside
        className={`fixed top-0 left-0 h-full w-60 bg-gray-900 text-gray-200 z-50 flex flex-col transform transition-transform duration-200 md:hidden ${
          drawerOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="px-4 pt-6 pb-2 flex items-center justify-between">
          <div>
            <span className="text-white font-bold text-base">GarageCarlos</span>
            <span className="block text-xs text-gray-400">Admin Panel</span>
          </div>
          <button
            onClick={() => setDrawerOpen(false)}
            className="text-gray-400 hover:text-white text-xl p-1"
            aria-label="Close menu"
          >
            ✕
          </button>
        </div>
        {sidebarContent(true)}
      </aside>

      {/* Main content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Header */}
        <header className="bg-white border-b border-gray-200 px-4 md:px-6 py-3 flex items-center justify-between flex-shrink-0">
          <div className="flex items-center gap-3">
            <button
              className="md:hidden text-gray-600 hover:text-gray-900 p-1"
              onClick={() => setDrawerOpen(true)}
              aria-label="Open menu"
            >
              ☰
            </button>
            <span className="font-semibold text-gray-800 text-sm hidden md:block">
              GarageCarlos
            </span>
          </div>
          <div className="flex items-center gap-3">
            <span className="text-xs text-gray-500 hidden sm:block">
              {currentUser?.email}
            </span>
            <button
              onClick={handleLogout}
              className="text-xs px-3 py-1.5 bg-red-500 hover:bg-red-600 text-white rounded-lg transition-colors"
            >
              Sign Out
            </button>
          </div>
        </header>

        {/* Page content */}
        <main className="flex-1 p-4 md:p-6">{children}</main>
      </div>
    </div>
  )
}
