import React, { useState } from "react"
import { graphql } from "gatsby"
import { formatDistanceToNow } from "date-fns"
import { useRequireAuth } from "../../hooks/useRequireAuth"
import { useAppointmentRequests, AppointmentRequest } from "../../hooks/useAppointmentRequests"
import AdminLayout from "../../components/admin/AdminLayout"
import ApproveRequestModal from "../../components/admin/Requests/ApproveRequestModal"
import { useToast } from "../../context/ToastContext"

type Tab = "pending" | "reviewed"

function RequestCard({
  request,
  onApprove,
  onReject,
}: {
  request: AppointmentRequest
  onApprove?: () => void
  onReject?: () => void
}) {
  const serviceLabel =
    request.serviceType === "custom"
      ? request.customDescription || "Custom"
      : request.serviceType.replace(/-/g, " ").replace(/\b\w/g, c => c.toUpperCase())

  const timeOfDayLabel: Record<string, string> = {
    morning: "🌅 Morning",
    afternoon: "☀️ Afternoon",
    any: "🕐 Any time",
  }

  const statusColors: Record<string, string> = {
    pending: "bg-yellow-100 text-yellow-700",
    approved: "bg-green-100 text-green-700",
    rejected: "bg-red-100 text-red-600",
  }

  return (
    <div className="bg-white rounded-xl border border-gray-200 p-4 space-y-3">
      <div className="flex items-start justify-between gap-3">
        <div>
          <p className="font-semibold text-gray-800 text-sm">{request.clientName}</p>
          <p className="text-xs text-gray-500">
            {request.phone}
            {request.email ? ` · ${request.email}` : ""}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0">
          <span className={`text-xs px-2 py-0.5 rounded-full font-medium ${statusColors[request.status]}`}>
            {request.status.charAt(0).toUpperCase() + request.status.slice(1)}
          </span>
          <span className="text-xs text-gray-400">
            {formatDistanceToNow(request.createdAt, { addSuffix: true })}
          </span>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-sm">
        <div>
          <span className="text-xs text-gray-400 block">Service</span>
          <span className="text-gray-700 capitalize">{serviceLabel}</span>
        </div>
        <div>
          <span className="text-xs text-gray-400 block">Preferred time</span>
          <span className="text-gray-700">{timeOfDayLabel[request.preferredTimeOfDay]}</span>
        </div>
        <div className="col-span-2">
          <span className="text-xs text-gray-400 block">Preferred dates</span>
          <span className="text-gray-700">
            {request.preferredDates.length > 0 ? request.preferredDates.join(" · ") : "—"}
          </span>
        </div>
        {request.notes && (
          <div className="col-span-2">
            <span className="text-xs text-gray-400 block">Notes</span>
            <span className="text-gray-600 italic text-xs">"{request.notes}"</span>
          </div>
        )}
        {request.status !== "pending" && request.reviewedAt && (
          <div className="col-span-2">
            <span className="text-xs text-gray-400 block">Reviewed</span>
            <span className="text-gray-500 text-xs">
              {formatDistanceToNow(request.reviewedAt, { addSuffix: true })}
              {request.reviewedBy ? ` by ${request.reviewedBy}` : ""}
            </span>
          </div>
        )}
      </div>

      {onApprove && onReject && (
        <div className="flex gap-2 pt-1">
          <button
            onClick={onApprove}
            className="flex-1 py-1.5 bg-green-600 hover:bg-green-700 text-white text-xs font-medium rounded-lg transition-colors"
          >
            ✓ Approve
          </button>
          <button
            onClick={onReject}
            className="flex-1 py-1.5 border border-red-200 text-red-600 hover:bg-red-50 text-xs font-medium rounded-lg transition-colors"
          >
            ✕ Reject
          </button>
        </div>
      )}
    </div>
  )
}

export default function RequestsPage() {
  const { currentUser, loading: authLoading } = useRequireAuth()
  const { requests, pendingCount, loading, approveRequest, rejectRequest } = useAppointmentRequests()
  const { showToast } = useToast()
  const [activeTab, setActiveTab] = useState<Tab>("pending")
  const [approving, setApproving] = useState<AppointmentRequest | null>(null)

  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  if (!currentUser) return null

  const pending = requests.filter(r => r.status === "pending")
  const reviewed = requests.filter(r => r.status !== "pending")

  async function handleReject(request: AppointmentRequest) {
    const confirmed = window.confirm(
      `Reject this request from ${request.clientName}? The client will not be notified automatically.`
    )
    if (!confirmed) return
    try {
      await rejectRequest(request.id, currentUser!.email ?? "")
      showToast("Request rejected", "success")
    } catch {
      showToast("Failed to reject request", "error")
    }
  }

  async function handleApproveConfirm(id: string, payload: import("../../hooks/useAppointmentRequests").ApprovePayload) {
    await approveRequest(id, payload)
    setApproving(null)
    showToast("Appointment created", "success")
  }

  const tabs: { key: Tab; label: string; count?: number }[] = [
    { key: "pending", label: "Pending", count: pendingCount },
    { key: "reviewed", label: "Reviewed" },
  ]

  return (
    <AdminLayout currentPath="/admin/requests">
      <div className="mb-6">
        <h1 className="text-xl font-bold text-gray-800">Requests</h1>
        <p className="text-sm text-gray-500 mt-0.5">Appointment requests submitted by clients.</p>
      </div>

      {/* Tabs */}
      <div className="flex gap-1 mb-6 border-b border-gray-200">
        {tabs.map(tab => (
          <button
            key={tab.key}
            onClick={() => setActiveTab(tab.key)}
            className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors -mb-px flex items-center gap-2 ${
              activeTab === tab.key
                ? "border-blue-600 text-blue-600"
                : "border-transparent text-gray-500 hover:text-gray-700"
            }`}
          >
            {tab.label}
            {tab.count !== undefined && tab.count > 0 && (
              <span className="bg-red-500 text-white text-xs font-bold rounded-full px-1.5 py-0.5 leading-none">
                {tab.count > 9 ? "9+" : tab.count}
              </span>
            )}
          </button>
        ))}
      </div>

      {loading ? (
        <div className="flex justify-center py-16">
          <div className="w-6 h-6 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
        </div>
      ) : activeTab === "pending" ? (
        pending.length === 0 ? (
          <div className="bg-white rounded-xl border border-gray-200 flex flex-col items-center justify-center py-16 text-gray-400 gap-2">
            <span className="text-4xl">🎉</span>
            <p className="text-sm">No pending requests.</p>
          </div>
        ) : (
          <div className="space-y-3">
            {pending.map(r => (
              <RequestCard
                key={r.id}
                request={r}
                onApprove={() => setApproving(r)}
                onReject={() => handleReject(r)}
              />
            ))}
          </div>
        )
      ) : reviewed.length === 0 ? (
        <div className="bg-white rounded-xl border border-gray-200 flex flex-col items-center justify-center py-16 text-gray-400 gap-2">
          <span className="text-4xl">📋</span>
          <p className="text-sm">No reviewed requests yet.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {reviewed.map(r => (
            <RequestCard key={r.id} request={r} />
          ))}
        </div>
      )}

      {approving && (
        <ApproveRequestModal
          request={approving}
          adminEmail={currentUser.email ?? ""}
          onConfirm={handleApproveConfirm}
          onClose={() => setApproving(null)}
        />
      )}
    </AdminLayout>
  )
}

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`
